'use strict';(async()=>{try{const r=await fetch('/api/public/app');const j=await r.json(),d=j.data;if(!r.ok||!j.ok)throw Error('下载服务暂时不可用');if(!d.published||!d.version){document.getElementById('version').textContent='安装包准备中，请稍后再来。';return;}document.getElementById('version').textContent=`版本 ${d.version}　${(d.size/1024/1024).toFixed(2)} MB`;document.getElementById('download').hidden=false;document.getElementById('qr').hidden=false;document.getElementById('hash').textContent='SHA-256：'+d.sha256;}catch(e){document.getElementById('version').textContent=e.message;}})();
